using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;

internal static class Program
{
    private static Mutex appMutex;

    [STAThread]
    private static void Main(string[] args)
    {
        if (CleanupWatchdog.TryRun(args))
        {
            return;
        }

        bool createdNew;
        appMutex = new Mutex(true, @"Global\AlgHelperSingleInstanceMutex", out createdNew);

        if (!createdNew)
        {
            MessageBox.Show(
                "AlgHelper już działa w zasobniku systemowym.",
                "AlgHelper",
                MessageBoxButtons.OK,
                MessageBoxIcon.Information
            );

            return;
        }

        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);

        try
        {
            Application.Run(new TrayAppContext());
        }
        finally
        {
            appMutex.ReleaseMutex();
            appMutex.Dispose();
        }
    }
}

internal static class CleanupWatchdog
{
    private const string WatchArgument = "--cleanup-watch";
    private const string MarkerFileName = ".alghelper-owned";
    private const string ManifestFileName = ".alghelper-manifest.txt";

    public static bool TryRun(string[] args)
    {
        if (args == null || args.Length < 3 || args[0] != WatchArgument)
        {
            return false;
        }

        int parentProcessId;

        if (!int.TryParse(args[1], out parentProcessId))
        {
            return true;
        }

        try
        {
            using (Process parent = Process.GetProcessById(parentProcessId))
            {
                parent.WaitForExit();
            }
        }
        catch
        {
            // If the parent is already gone, cleanup can run immediately.
        }

        Thread.Sleep(750);
        DeleteOwnedSnippetFiles(args[2]);
        return true;
    }

    public static void Start(int parentProcessId, string targetDir)
    {
        try
        {
            string exePath = Environment.ProcessPath;

            if (string.IsNullOrEmpty(exePath))
            {
                exePath = Application.ExecutablePath;
            }

            ProcessStartInfo psi = new ProcessStartInfo
            {
                FileName = exePath,
                UseShellExecute = false,
                CreateNoWindow = true,
                WindowStyle = ProcessWindowStyle.Hidden
            };

            psi.ArgumentList.Add(WatchArgument);
            psi.ArgumentList.Add(parentProcessId.ToString());
            psi.ArgumentList.Add(targetDir);

            Process.Start(psi);
        }
        catch
        {
            // Normal exit cleanup still runs; the watchdog is an extra crash guard.
        }
    }

    private static void DeleteOwnedSnippetFiles(string targetDir)
    {
        if (string.IsNullOrEmpty(targetDir) || !Directory.Exists(targetDir))
        {
            return;
        }

        string markerPath = Path.Combine(targetDir, MarkerFileName);
        string manifestPath = Path.Combine(targetDir, ManifestFileName);

        if (!File.Exists(markerPath) && !File.Exists(manifestPath))
        {
            return;
        }

        HashSet<string> fileNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        if (File.Exists(manifestPath))
        {
            foreach (string line in File.ReadAllLines(manifestPath))
            {
                string fileName = line.Trim();

                if (fileName.EndsWith(".snippet", StringComparison.OrdinalIgnoreCase)
                    && string.Equals(fileName, Path.GetFileName(fileName), StringComparison.Ordinal))
                {
                    fileNames.Add(fileName);
                }
            }
        }

        if (fileNames.Count == 0)
        {
            foreach (string filePath in Directory.GetFiles(targetDir, "alg_*.snippet"))
            {
                fileNames.Add(Path.GetFileName(filePath));
            }
        }

        foreach (string fileName in fileNames)
        {
            string filePath = Path.Combine(targetDir, fileName);

            if (File.Exists(filePath))
            {
                File.Delete(filePath);
            }
        }

        DeleteFileIfExists(manifestPath);
        DeleteFileIfExists(markerPath);

        if (Directory.Exists(targetDir) && Directory.GetFileSystemEntries(targetDir).Length == 0)
        {
            Directory.Delete(targetDir, false);
        }
    }

    private static void DeleteFileIfExists(string filePath)
    {
        if (File.Exists(filePath))
        {
            File.Delete(filePath);
        }
    }
}

internal sealed class TrayAppContext : ApplicationContext
{
    private readonly NotifyIcon trayIcon;
    private readonly string baseSnippetDir;
    private readonly string targetDir;
    private readonly string githubUrl = "https://github.com/bearbine";
    private readonly string version = "1.8.1";
    private const string MarkerFileName = ".alghelper-owned";
    private const string ManifestFileName = ".alghelper-manifest.txt";
    private bool notificationsEnabled = false;
    private ToolStripMenuItem notificationsItem;
    private bool cleanupDone = false;
    private bool cleanupInProgress = false;

    private static readonly Dictionary<string, string> Snippets = new Dictionary<string, string>
    {
            ["alg_51_lista_jedno.snippet"] = "",
            ["alg_510_nawiasy.snippet"] = "",
            ["alg_52_lista_ogon.snippet"] = "",
            ["alg_53_wydarzenia.snippet"] = "",
            ["alg_54_lista_dwu.snippet"] = "",
            ["alg_55_anagramy.snippet"] = "",
            ["alg_56_duplikaty.snippet"] = "",
            ["alg_57_stos.snippet"] = "",
            ["alg_57_stos_lista.snippet"] = "",
            ["alg_57_stos_tab.snippet"] = "",
            ["alg_58_kolejka_tab.snippet"] = "",
            ["alg_59_palindrom.snippet"] = "",
            ["alg_61_kolejka_prio.snippet"] = "",
            ["alg_62_kolejka_max.snippet"] = "",
            ["alg_63_kolejka_czas.snippet"] = "",
            ["alg_64_zgloszenia.snippet"] = "",
            ["alg_65_scal_tablice.snippet"] = "",
            ["alg_66_zakres_tablice.snippet"] = "",
            ["alg_71_graf_wszerz.snippet"] = "",
            ["alg_72_graf_wglab.snippet"] = "",
            ["alg_72_graf_wglab_rek.snippet"] = "",
            ["alg_72_graf_wglab_stos.snippet"] = "",
            ["alg_73_graf_skier.snippet"] = "",
            ["alg_74_graf_spojny.snippet"] = "",
            ["alg_75_dijkstra.snippet"] = "",
            ["alg_76_drogi_miasta.snippet"] = "",
            ["alg_76_kruskal.snippet"] = "",
            ["alg_77_drzewo_min.snippet"] = "",
            ["alg_77_prim.snippet"] = ""
    };

    private string MarkerPath
    {
        get { return Path.Combine(targetDir, MarkerFileName); }
    }

    private string ManifestPath
    {
        get { return Path.Combine(targetDir, ManifestFileName); }
    }

    public TrayAppContext()
    {
        string documents = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);

        baseSnippetDir = Path.Combine(
            documents,
            "Visual Studio 2022",
            "Code Snippets",
            "Visual C#",
            "My Code Snippets"
        );

        targetDir = Path.Combine(baseSnippetDir, "AlgHelper");
        CleanupLeftoversFromPreviousRun();
        CleanupWatchdog.Start(Environment.ProcessId, targetDir);

        ContextMenuStrip menu = new ContextMenuStrip
        {
            Renderer = new AlgHelperMenuRenderer(),
            BackColor = Color.FromArgb(250, 250, 252),
            ForeColor = Color.FromArgb(32, 36, 44),
            Font = new Font("Segoe UI", 9, FontStyle.Regular),
            Padding = new Padding(6, 6, 6, 6),
            ShowImageMargin = true
        };

        ToolStripLabel titleItem = new ToolStripLabel("AlgHelper 1.8.1")
        {
            ForeColor = Color.FromArgb(0, 92, 184),
            Font = new Font("Segoe UI Semibold", 9, FontStyle.Bold),
            Padding = new Padding(9, 5, 12, 5),
            TextAlign = ContentAlignment.MiddleLeft
        };

        ToolStripMenuItem installItem = new ToolStripMenuItem("Zainstaluj / odśwież");
        installItem.Image = LoadEmbeddedBitmap("AlgHelper.Resources.install.png");
        installItem.Click += (_, __) => InstallSnippets();

        ToolStripMenuItem openFolderItem = new ToolStripMenuItem("Folder snippetów");
        openFolderItem.Image = LoadEmbeddedBitmap("AlgHelper.Resources.folder.png");
        openFolderItem.Click += (_, __) => OpenSnippetFolder();

        ToolStripMenuItem listItem = new ToolStripMenuItem("Licznik aktywnych");
        listItem.Image = LoadEmbeddedBitmap("AlgHelper.Resources.count.png");
        listItem.Click += (_, __) => ShowSnippetCount();

        notificationsItem = new ToolStripMenuItem("Powiadomienia: wyłączone");
        notificationsItem.Image = LoadEmbeddedBitmap("AlgHelper.Resources.bell.png");
        notificationsItem.Click += (_, __) => ToggleNotifications();

        ToolStripMenuItem aboutItem = new ToolStripMenuItem("O AlgHelper");
        aboutItem.Image = LoadEmbeddedBitmap("AlgHelper.Resources.about.png");
        aboutItem.Click += (_, __) => ShowAbout();

        ToolStripMenuItem exitItem = new ToolStripMenuItem("Zamknij i posprzątaj");
        exitItem.Image = LoadEmbeddedBitmap("AlgHelper.Resources.exit.png");
        exitItem.Click += (_, __) => ExitApp();

        StyleMenuItem(installItem);
        StyleMenuItem(openFolderItem);
        StyleMenuItem(listItem);
        StyleMenuItem(notificationsItem);
        StyleMenuItem(aboutItem);
        StyleMenuItem(exitItem);

        menu.Items.Add(titleItem);
        menu.Items.Add(new ToolStripSeparator());
        menu.Items.Add(installItem);
        menu.Items.Add(new ToolStripSeparator());
        menu.Items.Add(openFolderItem);
        menu.Items.Add(listItem);
        menu.Items.Add(notificationsItem);
        menu.Items.Add(new ToolStripSeparator());
        menu.Items.Add(aboutItem);
        menu.Items.Add(new ToolStripSeparator());
        menu.Items.Add(exitItem);

        trayIcon = new NotifyIcon
        {
            Text = "AlgHelper",
            Icon = LoadEmbeddedIcon(),
            ContextMenuStrip = menu,
            Visible = true
        };

        trayIcon.DoubleClick += (_, __) => ShowSnippetCount();

        Application.ApplicationExit += (_, __) => DeleteSnippetFolderOnExit(showErrors: false);
        AppDomain.CurrentDomain.ProcessExit += (_, __) => DeleteSnippetFolderOnExit(showErrors: false);



    }

    private static void StyleMenuItem(ToolStripMenuItem item)
    {
        item.ForeColor = Color.FromArgb(32, 36, 44);
        item.Margin = new Padding(1, 1, 1, 1);
        item.Padding = new Padding(8, 5, 14, 5);
        item.ImageScaling = ToolStripItemImageScaling.SizeToFit;
    }

    private Icon LoadEmbeddedIcon()
    {
        Assembly assembly = Assembly.GetExecutingAssembly();

        using (Stream stream = assembly.GetManifestResourceStream("AlgHelper.alghelper.ico"))
        {
            if (stream == null)
            {
                return SystemIcons.Application;
            }

            return (Icon)new Icon(stream).Clone();
        }
    }

    private Bitmap LoadEmbeddedBitmap(string resourceName)
    {
        Assembly assembly = Assembly.GetExecutingAssembly();

        using (Stream stream = assembly.GetManifestResourceStream(resourceName))
        {
            if (stream == null)
            {
                Bitmap fallback = new Bitmap(24, 24);

                using (Graphics g = Graphics.FromImage(fallback))
                {
                    g.Clear(Color.Transparent);
                    g.FillEllipse(Brushes.DimGray, 3, 3, 18, 18);
                }

                return fallback;
            }

            return new Bitmap(stream);
        }
    }

    private void Notify(string title, string text, ToolTipIcon icon)
    {
        if (!notificationsEnabled)
        {
            return;
        }

        trayIcon.ShowBalloonTip(2500, title, text, icon);
    }

    private void ToggleNotifications()
    {
        notificationsEnabled = !notificationsEnabled;
        notificationsItem.Text = notificationsEnabled
            ? "Powiadomienia: włączone"
            : "Powiadomienia: wyłączone";

        if (notificationsEnabled)
        {
            trayIcon.ShowBalloonTip(
                1800,
                "AlgHelper",
                "Powiadomienia zostały włączone.",
                ToolTipIcon.Info
            );
        }
    }

    private void CleanupLeftoversFromPreviousRun()
    {
        try
        {
            DeleteOwnedSnippetFiles(requireOwnership: true, deleteFolderIfEmpty: true);
        }
        catch
        {
            // Startup cleanup is best-effort; visible cleanup errors are shown on manual exit.
        }
    }

    private bool HasOwnershipMarker()
    {
        return File.Exists(MarkerPath) || File.Exists(ManifestPath);
    }

    private static bool IsPlainSnippetFileName(string fileName)
    {
        return fileName.EndsWith(".snippet", StringComparison.OrdinalIgnoreCase)
            && string.Equals(fileName, Path.GetFileName(fileName), StringComparison.Ordinal);
    }

    private HashSet<string> GetOwnedSnippetFileNames()
    {
        HashSet<string> fileNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (string fileName in Snippets.Keys)
        {
            fileNames.Add(fileName);
        }

        if (File.Exists(ManifestPath))
        {
            foreach (string line in File.ReadAllLines(ManifestPath))
            {
                string fileName = line.Trim();

                if (IsPlainSnippetFileName(fileName))
                {
                    fileNames.Add(fileName);
                }
            }
        }

        return fileNames;
    }

    private void WriteOwnershipFiles()
    {
        File.WriteAllText(
            MarkerPath,
            "Owned by AlgHelper " + version + ". Delete only through AlgHelper cleanup." + Environment.NewLine
        );

        List<string> manifestLines = new List<string>(Snippets.Keys);
        manifestLines.Sort(StringComparer.OrdinalIgnoreCase);
        File.WriteAllLines(ManifestPath, manifestLines);
    }

    private static void DeleteFileIfExists(string filePath)
    {
        if (File.Exists(filePath))
        {
            File.Delete(filePath);
        }
    }

    private int DeleteOwnedSnippetFiles(bool requireOwnership, bool deleteFolderIfEmpty)
    {
        if (!Directory.Exists(targetDir))
        {
            return 0;
        }

        if (requireOwnership && !HasOwnershipMarker())
        {
            return 0;
        }

        int removed = 0;

        foreach (string fileName in GetOwnedSnippetFileNames())
        {
            string filePath = Path.Combine(targetDir, fileName);

            if (File.Exists(filePath))
            {
                File.Delete(filePath);
                removed++;
            }
        }

        DeleteFileIfExists(ManifestPath);
        DeleteFileIfExists(MarkerPath);

        if (deleteFolderIfEmpty && Directory.Exists(targetDir) && Directory.GetFileSystemEntries(targetDir).Length == 0)
        {
            Directory.Delete(targetDir, false);
        }

        return removed;
    }

    private void InstallSnippets()
    {
        try
        {
            Directory.CreateDirectory(targetDir);
            DeleteOwnedSnippetFiles(requireOwnership: false, deleteFolderIfEmpty: false);
            WriteOwnershipFiles();

            int installed = 0;

            foreach (var item in Snippets)
            {
                string filePath = Path.Combine(targetDir, item.Key);
                byte[] data = Convert.FromBase64String(item.Value);
                File.WriteAllBytes(filePath, data);
                installed++;
            }

            Notify(
                "AlgHelper",
                "Aktywne snippety: " + installed + ".",
                ToolTipIcon.Info
            );

            if (!notificationsEnabled)
            {
                MessageBox.Show(
                    "Zainstalowano/odświeżono snippetów: " + installed + ".",
                    "AlgHelper",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Information
                );
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                "Nie udało się zainstalować snippetów.\n\n" + ex.Message,
                "Błąd",
                MessageBoxButtons.OK,
                MessageBoxIcon.Error
            );
        }
    }

    private void OpenSnippetFolder()
    {
        try
        {
            Directory.CreateDirectory(baseSnippetDir);

            ProcessStartInfo psi = new ProcessStartInfo
            {
                FileName = baseSnippetDir,
                UseShellExecute = true
            };

            Process.Start(psi);
        }
        catch (Exception ex)
        {
            MessageBox.Show(
                "Nie udało się otworzyć folderu snippetów.\n\n" + ex.Message,
                "Błąd",
                MessageBoxButtons.OK,
                MessageBoxIcon.Error
            );
        }
    }

    private void ShowSnippetCount()
    {
        int count = 0;

        if (Directory.Exists(targetDir))
        {
            foreach (string fileName in Snippets.Keys)
            {
                if (File.Exists(Path.Combine(targetDir, fileName)))
                {
                    count++;
                }
            }
        }

        string folderInfo = Directory.Exists(targetDir)
            ? targetDir
            : targetDir + "\n(folder AlgHelper jeszcze nie istnieje)";

        MessageBox.Show(
            "Folder:\n" + folderInfo + "\n\nZainstalowane snippety AlgHelper: " + count,
            "AlgHelper",
            MessageBoxButtons.OK,
            MessageBoxIcon.Information
        );
    }

    private void ShowAbout()
    {
        using (AboutForm form = new AboutForm(
            LoadEmbeddedBitmap("AlgHelper.Resources.author.png"),
            githubUrl,
            version
        ))
        {
            form.ShowDialog();
        }
    }

    private void ExitApp()
    {
        DeleteSnippetFolderOnExit();

        trayIcon.Visible = false;
        trayIcon.Dispose();
        Application.Exit();
    }

    private void DeleteSnippetFolderOnExit(bool showErrors = true)
    {
        if (cleanupDone || cleanupInProgress)
        {
            return;
        }

        cleanupInProgress = true;

        try
        {
            DeleteOwnedSnippetFiles(requireOwnership: true, deleteFolderIfEmpty: true);
            cleanupDone = true;
        }
        catch (Exception ex)
        {
            if (showErrors)
            {
                MessageBox.Show(
                    "Nie udało się usunąć snippetów AlgHelper przy zamykaniu.\n\n" + ex.Message,
                    "AlgHelper",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Warning
                );
            }
        }
        finally
        {
            cleanupInProgress = false;
        }
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing)
        {
            DeleteSnippetFolderOnExit();
            trayIcon.Dispose();
        }

        base.Dispose(disposing);
    }
}

internal sealed class AlgHelperMenuRenderer : ToolStripProfessionalRenderer
{
    public AlgHelperMenuRenderer()
        : base(new AlgHelperColorTable())
    {
        RoundedEdges = true;
    }

    protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e)
    {
        Rectangle bounds = new Rectangle(Point.Empty, e.Item.Size);

        if (e.Item.Selected)
        {
            using (SolidBrush brush = new SolidBrush(Color.FromArgb(229, 241, 255)))
            {
                e.Graphics.FillRectangle(brush, bounds);
            }

            using (SolidBrush accent = new SolidBrush(Color.FromArgb(0, 120, 212)))
            {
                e.Graphics.FillRectangle(accent, 0, 0, 3, bounds.Height);
            }
        }
        else
        {
            using (SolidBrush brush = new SolidBrush(Color.FromArgb(250, 250, 252)))
            {
                e.Graphics.FillRectangle(brush, bounds);
            }
        }
    }

    protected override void OnRenderImageMargin(ToolStripRenderEventArgs e)
    {
        using (SolidBrush brush = new SolidBrush(Color.FromArgb(241, 246, 252)))
        {
            e.Graphics.FillRectangle(brush, e.AffectedBounds);
        }
    }

    protected override void OnRenderSeparator(ToolStripSeparatorRenderEventArgs e)
    {
        int y = e.Item.Height / 2;

        using (Pen pen = new Pen(Color.FromArgb(218, 225, 233)))
        {
            e.Graphics.DrawLine(pen, 34, y, e.Item.Width - 8, y);
        }
    }
}

